import { DefaultSeo } from "next-seo";

function MyApp({ Component, pageProps }) {
  return (
    <>
      <DefaultSeo
        title="My Next.js App"
        description="A description of my Next.js app"
        openGraph={{
          type: "website",
          locale: "en_IE",
          url: "https://www.example.com/",
          site_name: "My Next.js App",
        }}
      />
      <Component {...pageProps} />
    </>
  );
}

export default MyApp;
